  assertThat(indexOfInt).isEqualTo(-1);

  assertThat(list.lastIndexOf(new JsonPrimitive(1))).isEqualTo(1);
  assertThat(list.lastIndexOf(new JsonPrimitive(2))).isEqualTo(-1);
  assertThat(list.lastIndexOf(null)).isEqualTo(-1);
}

