private JsonReader createReaderForIntegerMismatch() throws IOException {
  JsonReader reader = new JsonReader(reader("[1.5]"));
  reader.beginArray();
  return reader;
}

@Test
public void testIntegerMismatchFailuresDoNotAdvance_nextIntThrows() throws IOException {
  JsonReader reader = createReaderForIntegerMismatch();
  assertThrows(
      "nextInt should throw NumberFormatException for a non‑integer value",
      NumberFormatException.class,
      () -> reader.nextInt());
  // Verify that the reader can be closed without advancing further
  reader.endArray();
}

@Test
public void testIntegerMismatchFailuresDoNotAdvance_nextDoubleAfterIntFailure() throws IOException {
  JsonReader reader = createReaderForIntegerMismatch();
  // First, verify that nextInt fails as expected
  assertThrows(
      "nextInt should throw NumberFormatException for a non‑integer value",
      NumberFormatException.class,
      () -> reader.nextInt());
  // Then, confirm the reader has not advanced and can still read the double value
  assertThat(reader.nextDouble()).isEqualTo(1.5d);
  reader.endArray();
}

