  reader.setStrictness(Strictness.STRICT);

  expected = assertThrows(IOException.class, reader::nextBoolean);
  assertThat(expected)
      .hasMessageThat()
      .startsWith(
          "Use JsonReader.setStrictness(Strictness.LENIENT) to accept malformed JSON"
              + " at line 1 column 1 path $\n");
}

