/** Helper to create a JsonWriter that has already started an array. */
private JsonWriter createArrayWriter(StringWriter stringWriter) throws IOException {
    JsonWriter jsonWriter = new JsonWriter(stringWriter);
    jsonWriter.beginArray();
    return jsonWriter;
}

/** Helper to finish the array, close the writer and return the resulting JSON string. */
private String closeAndGetJson(JsonWriter jsonWriter, StringWriter stringWriter) throws IOException {
    jsonWriter.endArray();
    jsonWriter.close();
    return stringWriter.toString();
}

