/** Creates a lenient JsonReader that reads a JSON document spanning multiple buffers. */
private JsonReader createLenientReaderForReadAcrossBuffers() throws IOException {
    // Build a JSON string that forces the reader to span more than one internal buffer.
    String json = "#" + repeat(' ', JsonReader.BUFFER_SIZE - 3) + "\n)]}'\n3";
    JsonReader reader = new JsonReader(reader(json));
