    File in = new File(tempDir, "news-com-au-home.html");
    Files.copy(source.toPath(), in.toPath(), StandardCopyOption.REPLACE_EXISTING);
    assertTrue(in.exists(), "Copied HTML file should exist in the temporary directory");

