    assertFalse("Two documents with identical content should not be equal (different instances)", docA.equals(docB));

    // A document must be equal to itself (reflexivity)
    assertTrue("Document should be equal to itself", docA.equals(docA));

    // Redundant assertion removed:
    // assertEquals("Hash code should be consistent for the same object", docA.hashCode(), docA.hashCode()); // Redundant assertion, commented out for clarity.

    // Documents with different content should yield different hash codes
    assertFalse("Documents with different content should have different hash codes", docA.hashCode() == docC.hashCode());
}

