/**
 * Parameterized test covering the various class attribute formats and expected outcomes.
 */
@ParameterizedTest(name = "hasClass(\"{1}\") on element with class attribute \"{0}\" should be {2}")
@CsvSource({
    // exact match
    "'toto',                'toto',               true",
    // leading space
    "' toto',               'toto',               true",
    // trailing space
    "'toto ',               'toto',               true",
    // tab and space
    "'\\ttoto ',            'toto',               true",
    // multiple surrounding spaces
    "'  toto ',            'toto',               true",
    // no match simple
    "'ab',                  'toto',               false",
    // blank class attribute
    "'     ',                'toto',               false",
    // substring not a separate token
    "'tototo',              'toto',               false",
    // exact long name with trailing spaces
    "'raulpismuth  ',       'raulpismuth',        true",
    // middle token among others
    "'abcd  raulpismuth efgh', 'raulpismuth',    true",
    // last token without trailing space
    "'abcd efgh raulpismuth',   'raulpismuth',    true",
    // last token with trailing space
    "'abcd efgh raulpismuth ',  'raulpismuth',    true"
})
public void testHasClassDomMethods_parameterized(String classAttr, String queryClass, boolean expected) {
    Element el = createElementWithClass(classAttr);
    if (expected) {
        assertTrue(
            String.format("Element with class attribute \"%s\" should contain class \"%s\".", classAttr, queryClass),
            el.hasClass(queryClass)
        );
    } else {
        assertFalse(
            String.format("Element with class attribute \"%s\" should NOT contain class \"%s\".", classAttr, queryClass),
            el.hasClass(queryClass)
        );
    }
}

