proposals.refactored:
private static final int EXPECTED_ATTRIBUTE_COUNT = 3;
private static final List<String> EXPECTED_VALUES = Arrays.asList("1", "2", "3");

@Test
public void testIteratorHasNext() {
    Attributes a = new Attributes();
    a.put("Tot", "1");
    a.put("Hello", "2");
    a.put("data-name", "3");

    verifyAttributesIteration(a, EXPECTED_VALUES);
    assertEquals(
            "Total number of attributes should be " + EXPECTED_ATTRIBUTE_COUNT,
            EXPECTED_ATTRIBUTE_COUNT,
            a.size()
    );
}

private void verifyAttributesIteration(Attributes attrs, List<String> expectedValues) {
    int index = 0;
    for (Attribute attribute : attrs) {
        String expected = expectedValues.get(index);
        assertEquals(
                "Attribute at index " + index + " should have value " + expected,
                expected,
                attribute.getValue()
        );
        index++;
    }
    assertEquals(
            "Number of iterated attributes should match expected list size",
            expectedValues.size(),
            index
    );
}

